74	@RestController
75	@CrossOrigin(exposedHeaders = "errors, content-type")
76	@RequestMapping("/api")
77	public class OwnerRestControllerV1 implements OwnersApi {
78	
79	    /**
80	     * Dedicated audit logger. On a successful owner create an audit line carrying the owner id,
81	     * the {@code customerCode} and the {@code registrationDate} is emitted to this named logger.
82	     */
83	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
84	
85	    private final ClinicService clinicService;
86	
87	    private final OwnerMapper ownerMapper;
88	
89	    private final PetMapper petMapper;
90	
91	    private final VisitMapper visitMapper;
92	
93	    private final HttpServletRequest request;
94	
95	    /**
96	     * The HTTP header carrying a client-supplied idempotency token for owner creation.
97	     */
98	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
99	
100	    /**
101	     * Remembers the owner originally created under each seen {@code Idempotency-Key}. A create that
102	     * repeats a key already present here is replayed - the stored owner is returned with 200 instead
103	     * of creating a duplicate.
104	     */
105	    private final Map<String, OwnerDto> idempotentCreates = new ConcurrentHashMap<>();
