134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
137	        Owner owner = this.clinicService.findOwnerById(ownerId);
138	        if (owner == null) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
142	    }
143	
144	    /**
145	     * Rejects an owner payload that is missing or blank in any of the required fields
146	     * (firstName, lastName, address, city, telephone). Bean Validation on the request body
147	     * already rejects {@code null} values and empty strings, but treats a whitespace-only
148	     * value as present; this guard closes that gap so a blank in any required field is
149	     * reported. The thrown exception is translated to a 400 whose {@code errors} array lists
150	     * the name of each offending field.
151	     */
152	    private void rejectMissingOrBlankFields(OwnerFieldsDto ownerFieldsDto, String normalizedAddress) {
153	        List<String> missing = new ArrayList<>();
154	        if (isBlank(ownerFieldsDto.getFirstName())) {
155	            missing.add("firstName");
156	        }
157	        if (isBlank(ownerFieldsDto.getLastName())) {
158	            missing.add("lastName");
159	        }
160	        if (isBlank(normalizedAddress)) {
161	            missing.add("address");
162	        }
163	        if (isBlank(ownerFieldsDto.getCity())) {
164	            missing.add("city");
165	        }
166	        if (isBlank(ownerFieldsDto.getTelephone())) {
167	            missing.add("telephone");
168	        }
169	        if (!missing.isEmpty()) {
170	            throw new MissingOwnerFieldsException(missing);
171	        }
172	    }
173	
174	    private static boolean isBlank(String value) {
175	        return value == null || value.isBlank();
176	    }
177	
178	    /**
179	     * Matches a well-formed E.164 telephone: a leading '+' followed by 8 to 15 digits.
180	     */
181	    private static final Pattern E164_PATTERN = Pattern.compile("\\+\\d{8,15}");
182	
183	    /**
184	     * Required national-number length per country calling code. When the normalized E.164 number
185	     * begins with one of these codes, the digits that follow must number exactly the mapped value:
186	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Codes absent from
187	     * this map carry no per-country length rule beyond the generic E.164 8-to-15-digit bound.
188	     */
189	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
190	        "+61", 9,
191	        "+1", 10);
192	
193	    /**
194	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
195	     * stripped. When a leading '+' (with its country code) is present it is kept as-is; otherwise
196	     * the country code '+61' is assumed and a single leading '0' is dropped from the national
197	     * digits. The result must be a '+' followed by 8 to 15 digits, so e.g. '0412 345 678' is
198	     * stored as '+61412345678'. When the country code has a known national-number length ('+61'
199	     * requires 9 national digits, '+1' requires 10) the national digits must match it exactly. A
200	     * value that cannot form a valid E.164 number, or whose national length is wrong for its
201	     * country, is rejected via {@link InvalidTelephoneException}, which the exception handler
202	     * translates to a 400.
203	     */
204	    private static String normalizeTelephone(String telephone) {
205	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()\\[\\]]", "");
206	        String e164;
207	        if (cleaned.startsWith("+")) {
208	            e164 = cleaned;
209	        } else {
210	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
211	            e164 = "+61" + national;
212	        }
213	        if (!E164_PATTERN.matcher(e164).matches()) {
214	            throw new InvalidTelephoneException(telephone);
215	        }
216	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
217	            String code = rule.getKey();
218	            if (e164.startsWith(code)) {
219	                int nationalLength = e164.length() - code.length();
220	                if (nationalLength != rule.getValue()) {
221	                    throw new InvalidTelephoneException(telephone);
222	                }
223	                break;
224	            }
225	        }
226	        return e164;
227	    }
228	
229	    /**
230	     * Matches a well-formed postcode: exactly four digits.
231	     */
232	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("\\d{4}");
233	
234	    /**
235	     * The canonical region for each city that has one. A city absent from this table has no known
236	     * region and so accepts any 4-digit postcode. This is the same fixed city-to-region table used
237	     * to derive an owner's locality.
238	     */
239	    private static final Map<String, String> CITY_REGION = Map.of(
240	        "Sydney", "NSW",
241	        "Melbourne", "VIC",
242	        "Brisbane", "QLD");
243	
244	    /**
245	     * The inclusive 4-digit postcode range for each region, as {@code {low, high}}: NSW 2000-2099,
246	     * VIC 3000-3099, QLD 4000-4099.
247	     */
248	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
249	        "NSW", new int[] {2000, 2099},
250	        "VIC", new int[] {3000, 3099},
251	        "QLD", new int[] {4000, 4099});
252	
253	    /**
254	     * Validates an owner's optional postcode. A {@code null} postcode is left as-is (the field is
255	     * optional). When present it must be exactly four digits; and when the owner's city maps to a
256	     * known region it must fall within that region's inclusive postcode range (NSW 2000-2099, VIC
257	     * 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode. An
258	     * invalid or out-of-range value is rejected via {@link InvalidPostcodeException}, which the
259	     * exception handler translates to a 400.
260	     */
261	    private static void validatePostcode(String city, String postcode) {
262	        if (postcode == null) {
263	            return;
264	        }
265	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
266	            throw new InvalidPostcodeException(postcode);
267	        }
268	        String region = CITY_REGION.get(city);
269	        if (region == null) {
270	            return;
271	        }
272	        int[] range = REGION_POSTCODES.get(region);
273	        int value = Integer.parseInt(postcode);
274	        if (value < range[0] || value > range[1]) {
275	            throw new InvalidPostcodeException(postcode);
276	        }
277	    }
278	
279	    /**
280	     * A pragmatic syntactic email check: a non-empty local part, an {@code @}, and a domain that
281	     * carries at least one dot, with no whitespace anywhere. Deliberately permissive — it accepts
282	     * ordinary addresses while rejecting obvious non-addresses such as one lacking an {@code @}.
283	     */
284	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
285	
286	    /**
287	     * Disposable-email domains that an owner's email may not use. An address whose domain (the part
288	     * after the final {@code @}, compared case-insensitively) is one of these is rejected. Kept as a
289	     * fixed set so the block list is explicit and easy to extend.
290	     */
291	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
292	        "mailinator.com",
293	        "tempmail.com",
294	        "guerrillamail.com");
295	
296	    /**
297	     * Normalizes an optional owner email. A {@code null} email is left as-is (the field is
298	     * optional). When present it must be a syntactically valid address whose domain is not on the
299	     * disposable-domain block list; a valid value is lower-cased so it is stored and returned in
300	     * canonical form. An invalid or disposable-domain value is rejected via
301	     * {@link InvalidEmailException}, which the exception handler translates to a 400.
302	     */
303	    private static String normalizeEmail(String email) {
304	        if (email == null) {
305	            return null;
306	        }
307	        if (!EMAIL_PATTERN.matcher(email).matches()) {
308	            throw new InvalidEmailException(email);
309	        }
310	        String normalized = email.toLowerCase(Locale.ROOT);
311	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
312	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
313	            throw new InvalidEmailException(email);
314	        }
315	        return normalized;
316	    }
317	
318	    /**
319	     * The single derived identity of an owner: the 64-character lower-case SHA-256 hex digest over
320	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, into which all
321	     * duplicate detection is consolidated. Two owners are the same identity only when this whole key
322	     * matches: because the normalized telephone is part of the pre-image, two owners who share a
323	     * surname (same soundex) and postcode but carry different telephones have different identity
324	     * keys. A {@code null} email contributes an empty middle segment. This is the value returned to
325	     * callers as {@code identityKey}.
326	     */
327	    private static String identityKeyFor(String normalizedTelephone, String normalizedEmail, String lastName) {
328	        String preimage = normalizedTelephone + "|" + (normalizedEmail == null ? "" : normalizedEmail)
329	            + "|" + soundex(lastName);
330	        return sha256Hex(preimage);
331	    }
332	
333	    /**
334	     * The American Soundex code of a name: its first letter followed by up to three digits encoding
335	     * the remaining consonants (b/f/p/v->1, c/g/j/k/q/s/x/z->2, d/t->3, l->4, m/n->5, r->6), with
336	     * adjacent duplicate codes collapsed, vowels (and y) resetting the run, and h/w transparent so
337	     * consonants they separate are still treated as adjacent. The result is padded with zeros to
338	     * exactly four characters. A {@code null} or letterless name yields the empty string.
339	     */
340	    private static String soundex(String name) {
341	        if (name == null) {
342	            return "";
343	        }
344	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
345	        if (letters.isEmpty()) {
346	            return "";
347	        }
348	        StringBuilder code = new StringBuilder();
349	        code.append(letters.charAt(0));
350	        char prev = soundexCode(letters.charAt(0));
351	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
352	            char c = letters.charAt(i);
353	            if (c == 'H' || c == 'W') {
354	                continue;
355	            }
356	            char digit = soundexCode(c);
357	            if (digit != '0' && digit != prev) {
358	                code.append(digit);
359	            }
360	            prev = digit;
361	        }
362	        while (code.length() < 4) {
363	            code.append('0');
364	        }
365	        return code.toString();
366	    }
367	
368	    /**
369	     * The Soundex digit for a single upper-case letter, or {@code '0'} for a vowel, y, h or w (which
370	     * carry no code).
371	     */
372	    private static char soundexCode(char c) {
373	        return switch (c) {
374	            case 'B', 'F', 'P', 'V' -> '1';
375	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
376	            case 'D', 'T' -> '3';
377	            case 'L' -> '4';
378	            case 'M', 'N' -> '5';
379	            case 'R' -> '6';
380	            default -> '0';
381	        };
382	    }
383	
384	    /**
385	     * The full lower-case SHA-256 hex digest (64 characters) of the UTF-8 bytes of {@code value}.
386	     */
387	    private static String sha256Hex(String value) {
388	        try {
389	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
390	            StringBuilder sb = new StringBuilder(digest.length * 2);
391	            for (byte b : digest) {
392	                sb.append(String.format("%02x", b));
393	            }
394	            return sb.toString();
395	        } catch (NoSuchAlgorithmException ex) {
396	            throw new IllegalStateException("SHA-256 not available", ex);
397	        }
398	    }
399	
400	    /**
401	     * Rejects a create whose derived identity collides with an existing owner's, reported via
402	     * {@link DuplicateTelephoneException} which the handler translates to a 409. Duplicate detection
403	     * is now the single identity key: the new owner's {@link #identityKeyFor identityKey} (the
404	     * SHA-256 over {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}) is
405	     * compared against each existing owner's, ignoring owners flagged deleted. The email-domain
406	     * block list has already been applied while normalizing the email, so it takes effect first. An
407	     * existing telephone that cannot form a valid E.164 number is skipped rather than colliding.
408	     * Because the telephone is part of the key, two owners with the same surname and postcode but
409	     * different telephones no longer collide here - they are surfaced as a soft match instead. The
410	     * former separate telephone, email and household 409 blocks are all subsumed by this key.
411	     */
412	    private void rejectDuplicateIdentity(String normalizedTelephone, String normalizedEmail, String lastName) {
413	        String identityKey = identityKeyFor(normalizedTelephone, normalizedEmail, lastName);
414	        for (Owner existing : this.clinicService.findAllOwners()) {
415	            if (existing.isDeleted()) {
416	                continue;
417	            }
418	            String existingTelephone;
419	            try {
420	                existingTelephone = normalizeTelephone(existing.getTelephone());
421	            } catch (InvalidTelephoneException ex) {
422	                continue;
423	            }
424	            String existingEmail = existing.getEmail() == null ? null : existing.getEmail().toLowerCase(Locale.ROOT);
425	            String existingKey = identityKeyFor(existingTelephone, existingEmail, existing.getLastName());
426	            if (identityKey.equals(existingKey)) {
427	                throw new DuplicateTelephoneException(normalizedTelephone);
428	            }
429	        }
430	    }
431	
432	    /**
433	     * Collapses a value for household comparison: leading and trailing whitespace is trimmed, any
434	     * internal run of whitespace is reduced to a single space, and the result is lower-cased. This
435	     * is how both {@code lastName} and {@code address} are compared so that differences of case or
436	     * spacing do not defeat the duplicate-household check.
437	     */
438	    private static String collapse(String value) {
439	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
440	    }
441	
442	    /**
443	     * Normalizes an owner's address into a canonical form applied on every create: leading and
444	     * trailing whitespace is trimmed, any internal run of whitespace is reduced to a single space,
445	     * the value is upper-cased, and common street-type abbreviations are expanded on a per-word
446	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The result is stored
447	     * and returned, and is the form every address comparison (duplicate-household detection and the
448	     * shared {@code householdId}) uses. A {@code null} or whitespace-only input normalizes to the
449	     * empty string, which the required-field guard then rejects. The transformation is idempotent,
450	     * so normalizing an already-normalized address is a no-op.
451	     */
452	    private static String normalizeAddress(String address) {
453	        if (address == null) {
454	            return "";
455	        }
456	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
457	        if (collapsed.isEmpty()) {
458	            return "";
459	        }
460	        String[] tokens = collapsed.split(" ");
461	        StringBuilder sb = new StringBuilder(collapsed.length());
462	        for (int i = 0; i < tokens.length; i++) {
463	            String token = tokens[i];
464	            switch (token) {
465	                case "ST" -> token = "STREET";
466	                case "RD" -> token = "ROAD";
467	                case "AVE" -> token = "AVENUE";
468	                default -> {
469	                }
470	            }
471	            if (i > 0) {
472	                sb.append(' ');
473	            }
474	            sb.append(token);
475	        }
476	        return sb.toString();
477	    }
478	
479	    /**
480	     * Derives an owner's region code from its postcode, falling back to its city. A present postcode
481	     * that falls in a known region's inclusive 4-digit range wins (NSW 2000-2099, VIC 3000-3099, QLD
482	     * 4000-4099); otherwise the fixed city-to-region table is consulted (Sydney -> NSW, Melbourne ->
483	     * VIC, Brisbane -> QLD); a value resolved by neither is {@code "UNKNOWN"}. This is the single
484	     * region derivation shared by the {@code customerCode} and the owner's locality.
485	     */
486	    private static String deriveRegion(String city, String postcode) {
487	        if (postcode != null) {
488	            try {
489	                int pc = Integer.parseInt(postcode.trim());
490	                for (Map.Entry<String, int[]> range : REGION_POSTCODES.entrySet()) {
491	                    int[] bounds = range.getValue();
492	                    if (pc >= bounds[0] && pc <= bounds[1]) {
493	                        return range.getKey();
494	                    }
495	                }
496	            } catch (NumberFormatException ignored) {
497	                // not a numeric postcode; fall back to the city-to-region table
498	            }
499	        }
500	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
501	    }
502	
503	    /**
504	     * Builds the {@code customerCode} for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
505	     * where {@code REGION} is the region code derived from the owner's postcode (falling back to its
506	     * city) and {@code HASH8} is the first 8 upper-case hex characters of SHA-256 over
507	     * {@code normalizedTelephone + lastName} (e.g. {@code 'NSW-1A2B3C4D'}). This is a stable identity:
508	     * it carries no sequence number and depends only on the owner's own region, telephone and surname.
509	     */
510	    private static String customerCodeFor(String region, String normalizedTelephone, String lastName) {
511	        return region + "-" + sha256HexPrefix(normalizedTelephone + lastName, 8);
512	    }
513	
514	    /**
515	     * De-duplicates a freshly computed {@code customerCode} against the codes already carried by
516	     * existing owners. When the base code is unused it is returned unchanged; otherwise
517	     * {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that yields a code no
518	     * existing owner already holds. The count reflects the state prior to this create.
519	     */
520	    private String deduplicateCustomerCode(String baseCode) {
521	        Set<String> existingCodes = new HashSet<>();
522	        for (Owner existing : this.clinicService.findAllOwners()) {
523	            String code = existing.getCustomerCode();
524	            if (code != null) {
525	                existingCodes.add(code);
526	            }
527	        }
528	        if (!existingCodes.contains(baseCode)) {
529	            return baseCode;
530	        }
531	        int n = 2;
532	        while (existingCodes.contains(baseCode + "-" + n)) {
533	            n++;
534	        }
535	        return baseCode + "-" + n;
536	    }
537	
538	    /**
539	     * Returns the first {@code hexChars} upper-case hex characters of the SHA-256 digest of the UTF-8
540	     * bytes of {@code value}.
541	     */
542	    private static String sha256HexPrefix(String value, int hexChars) {
543	        try {
544	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
545	            StringBuilder sb = new StringBuilder(hexChars);
546	            for (byte b : digest) {
547	                if (sb.length() >= hexChars) {
548	                    break;
549	                }
550	                sb.append(String.format("%02X", b));
551	            }
552	            return sb.substring(0, hexChars);
553	        } catch (NoSuchAlgorithmException ex) {
554	            throw new IllegalStateException("SHA-256 not available", ex);
555	        }
556	    }
