558	    /**
559	     * Builds the {@code membershipNumber} for a newly created owner, formatted
560	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
561	     * fiscal year of the {@code registrationDate} (e.g. {@code 'SMI-0007-M27'}). The year
562	     * segment therefore matches the owner's {@code fiscalYear}.
563	     */
564	    private static String membershipNumberFor(String customerCode, LocalDate registrationDate) {
565	        return String.format("%s-M%02d", customerCode, fiscalYearOf(registrationDate) % 100);
566	    }
