568	    /**
569	     * The fiscal year, as a four-digit year, of a business-day-adjusted date. The fiscal year
570	     * starts on 1 July and is labelled by the calendar year in which it ends: a date on or after
571	     * 1 July belongs to the fiscal year ending the following calendar year, while an earlier date
572	     * belongs to the fiscal year ending in its own year.
573	     */
574	    private static int fiscalYearOf(LocalDate date) {
575	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
576	    }
