578	    /**
579	     * Derives the stable {@code householdId} for an owner from the collapsed {@code lastName} and
580	     * its {@code postcode} - the same pair used to detect a shared household. It is the first 12
581	     * lower-case hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. Because
582	     * it is a pure function of that pair, every owner in the same household - whether created first
583	     * or joining later via {@code sharesHousehold} - receives the identical, non-blank identifier
584	     * without needing to read any other owner's value. A {@code null} postcode contributes an empty
585	     * segment.
586	     */
587	    private static String householdIdFor(String lastName, String postcode) {
588	        String key = collapse(lastName) + "|" + (postcode == null ? "" : postcode);
589	        try {
590	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
591	            StringBuilder sb = new StringBuilder(12);
592	            for (byte b : digest) {
593	                if (sb.length() >= 12) {
594	                    break;
595	                }
596	                sb.append(String.format("%02x", b));
597	            }
598	            return sb.substring(0, 12);
599	        } catch (NoSuchAlgorithmException ex) {
600	            throw new IllegalStateException("SHA-256 not available", ex);
601	        }
602	    }
