604	    /**
605	     * Counts the existing owners who already share the given {@code firstName} and {@code lastName},
606	     * compared case-insensitively. This is evaluated before the new owner is saved, so it reflects
607	     * the state prior to this create and is stored on the owner as its {@code namesakeCount}.
608	     */
609	    private int countNamesakes(String firstName, String lastName) {
610	        int count = 0;
611	        for (Owner existing : this.clinicService.findAllOwners()) {
612	            if (firstName.equalsIgnoreCase(existing.getFirstName())
613	                && lastName.equalsIgnoreCase(existing.getLastName())) {
614	                count++;
615	            }
616	        }
617	        return count;
618	    }
