620	    /**
621	     * Counts the members of the household the new owner will belong to, as it stands after this
622	     * create. Every existing owner carrying the same {@code householdId} is counted, and the new
623	     * owner itself is added, so a value of 3 or more means the owner joins a household of at least
624	     * three members. This is evaluated with the new owner's {@code householdId} already set and is
625	     * stored on the owner as its {@code householdMemberCount}.
626	     */
627	    private int countHouseholdMembers(String householdId) {
628	        int count = 1;
629	        for (Owner existing : this.clinicService.findAllOwners()) {
630	            if (householdId.equals(existing.getHouseholdId())) {
631	                count++;
632	            }
633	        }
634	        return count;
635	    }
