637	    /**
638	     * Finds an existing owner that makes the new owner a <em>possible</em> (soft) duplicate: one
639	     * that is not a hard identity collision but whose {@code lastName} has the same
640	     * {@link #soundex soundex} code as the new owner's and whose {@code postcode} matches, while its
641	     * {@link #identityKeyFor identityKey} differs. The new owner's postcode must be present for a
642	     * soft match to be possible. When several existing owners qualify the one with the lowest id is
643	     * chosen. Returns the matching owner's id, or {@code null} when there is no soft match. This is
644	     * evaluated after the hard-duplicate check has already passed, so any surviving owner sharing the
645	     * surname's soundex and postcode necessarily has a different identity key (typically a different
646	     * telephone). A caller that declares {@code sharesHousehold} is deliberately joining an existing
647	     * household, so it is not flagged as a suspected duplicate.
648	     */
649	    private Integer findPossibleDuplicateOf(OwnerFieldsDto ownerFieldsDto, String normalizedTelephone,
650	                                            String normalizedEmail) {
651	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
652	            return null;
653	        }
654	        String postcode = ownerFieldsDto.getPostcode();
655	        if (postcode == null) {
656	            return null;
657	        }
658	        String lastName = ownerFieldsDto.getLastName();
659	        if (lastName == null) {
660	            return null;
661	        }
662	        String identityKey = identityKeyFor(normalizedTelephone, normalizedEmail, lastName);
663	        String soundex = soundex(lastName);
664	        Integer matchId = null;
665	        for (Owner existing : this.clinicService.findAllOwners()) {
666	            if (existing.isDeleted()) {
667	                continue;
668	            }
669	            if (!soundex.equals(soundex(existing.getLastName()))) {
670	                continue;
671	            }
672	            if (!postcode.equals(existing.getPostcode())) {
673	                continue;
674	            }
675	            String existingTelephone;
676	            try {
677	                existingTelephone = normalizeTelephone(existing.getTelephone());
678	            } catch (InvalidTelephoneException ex) {
679	                continue;
680	            }
681	            String existingEmail = existing.getEmail() == null ? null : existing.getEmail().toLowerCase(Locale.ROOT);
682	            String existingKey = identityKeyFor(existingTelephone, existingEmail, existing.getLastName());
683	            if (identityKey.equals(existingKey)) {
684	                continue;
685	            }
686	            if (existing.getId() != null && (matchId == null || existing.getId() < matchId)) {
687	                matchId = existing.getId();
688	            }
689	        }
690	        return matchId;
691	    }
