693	    /**
694	     * The tenure, in elapsed fiscal years, that an owner must exceed before its tenure contributes
695	     * membership points. Tenure is measured from the owner's {@code registrationDate}, so a newly
696	     * created owner (whose tenure is zero) never satisfies this and thus never earns the tenure
697	     * points on create.
698	     */
699	    private static final int TENURE_POINTS_THRESHOLD_FISCAL_YEARS = 1;
700	
701	    /**
702	     * The household size (number of members) at or above which an owner earns the household points.
703	     */
704	    private static final int HOUSEHOLD_POINTS_THRESHOLD = 3;
705	
706	    /**
707	     * Computes the {@code membershipPoints} for an owner. Points start at 0, gain 2 when an email is
708	     * present, gain 1 when the owner's {@code namesakeCount} is 0, gain 2 when the owner's household
709	     * has {@value #HOUSEHOLD_POINTS_THRESHOLD} or more members, and gain 3 when the owner's tenure
710	     * (elapsed fiscal years since its {@code registrationDate}) exceeds
711	     * {@value #TENURE_POINTS_THRESHOLD_FISCAL_YEARS}. Because a newly created owner has zero tenure,
712	     * the tenure points never apply on create.
713	     * Evaluated after the owner's email, namesakeCount, householdMemberCount and registrationDate
714	     * have been set.
715	     */
716	    private static int membershipPointsFor(Owner owner) {
717	        int points = 0;
718	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
719	            points += 2;
720	        }
721	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
722	            points += 1;
723	        }
724	        if (owner.getHouseholdMemberCount() != null
725	            && owner.getHouseholdMemberCount() >= HOUSEHOLD_POINTS_THRESHOLD) {
726	            points += 2;
727	        }
728	        if (tenureInFiscalYears(owner) > TENURE_POINTS_THRESHOLD_FISCAL_YEARS) {
729	            points += 3;
730	        }
731	        return points;
732	    }
733	
734	    /**
735	     * Maps {@code membershipPoints} to the numeric {@code membershipLevel}: level 1 for 0-1 points,
736	     * 2 for 2-3, 3 for 4-5, and 4 for 6 or more points.
737	     */
738	    private static int membershipLevelForPoints(int points) {
739	        if (points <= 1) {
740	            return 1;
741	        }
742	        if (points <= 3) {
743	            return 2;
744	        }
745	        if (points <= 5) {
746	            return 3;
747	        }
748	        return 4;
749	    }
750	
751	    /**
752	     * Caps a newly computed {@code membershipLevel} so it never exceeds one above the current maximum
753	     * {@code membershipLevel} among the new owner's household members - the existing, non-deleted
754	     * owners already carrying the same {@code householdId}. When the household has no existing member
755	     * (or none with a recorded level) no cap applies and the level is returned unchanged; otherwise the
756	     * level is limited to {@code max(member level) + 1}. The count reflects the state prior to this
757	     * create, as the new owner has not yet been saved.
758	     */
759	    private int capMembershipLevelByHousehold(int membershipLevel, String householdId) {
760	        Integer maxMemberLevel = null;
761	        for (Owner existing : this.clinicService.findAllOwners()) {
762	            if (existing.isDeleted()) {
763	                continue;
764	            }
765	            if (!householdId.equals(existing.getHouseholdId())) {
766	                continue;
767	            }
768	            Integer existingLevel = existing.getMembershipLevel();
769	            if (existingLevel == null) {
770	                continue;
771	            }
772	            if (maxMemberLevel == null || existingLevel > maxMemberLevel) {
773	                maxMemberLevel = existingLevel;
774	            }
775	        }
776	        if (maxMemberLevel == null) {
777	            return membershipLevel;
778	        }
779	        return Math.min(membershipLevel, maxMemberLevel + 1);
780	    }
781	
782	    /**
783	     * The owner's tenure in whole elapsed fiscal years: the number of 1 July fiscal-year boundaries
784	     * crossed between its {@code registrationDate} and the current server date. An owner with no
785	     * registration date, or one dated in the future, has a tenure of zero.
786	     */
787	    private static long tenureInFiscalYears(Owner owner) {
788	        LocalDate registrationDate = owner.getRegistrationDate();
789	        if (registrationDate == null) {
790	            return 0;
791	        }
792	        return Math.max(0, fiscalYearOf(LocalDate.now()) - fiscalYearOf(registrationDate));
793	    }
