795	    /**
796	     * The maximum number of owners any single city may contain. A create whose city already
797	     * holds this many owners is rejected.
798	     */
799	    private static final int CITY_CAPACITY = 50;
800	
801	    /**
802	     * Rejects a create whose city already contains {@value #CITY_CAPACITY} or more owners,
803	     * compared case-insensitively - the same way the city is matched when building the
804	     * {@code customerCode} sequence. The count reflects the state prior to this create. A city
805	     * at capacity is reported via {@link CityAtCapacityException}, which the exception handler
806	     * translates to a 409.
807	     */
808	    private void rejectCityAtCapacity(String city) {
809	        int count = 0;
810	        for (Owner existing : this.clinicService.findAllOwners()) {
811	            if (city.equalsIgnoreCase(existing.getCity())) {
812	                count++;
813	            }
814	        }
815	        if (count >= CITY_CAPACITY) {
816	            throw new CityAtCapacityException(city);
817	        }
818	    }
819	
820	    /**
821	     * The maximum number of owners that may be created on any single day (by
822	     * {@code registrationDate}). A create attempted once this many owners already carry the
823	     * current day's registration date is rejected.
824	     */
825	    private static final int DAILY_OWNER_LIMIT = 100;
826	
827	    /**
828	     * Rejects a create once {@value #DAILY_OWNER_LIMIT} or more owners already carry the given
829	     * business-day-adjusted {@code registrationDate} (the date the new owner will itself receive).
830	     * The count reflects the state prior to this create. When the limit is reached the create is
831	     * reported via {@link DailyOwnerLimitExceededException}, which the exception handler translates
832	     * to a 429 Too Many Requests.
833	     */
834	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
835	        int count = 0;
836	        for (Owner existing : this.clinicService.findAllOwners()) {
837	            if (registrationDate.equals(existing.getRegistrationDate())) {
838	                count++;
839	            }
840	        }
841	        if (count >= DAILY_OWNER_LIMIT) {
842	            throw new DailyOwnerLimitExceededException();
843	        }
844	    }
845	
846	    /**
847	     * The number of owners that must already carry a given {@code registrationDate} before a
848	     * create on that date is flagged with a bulk-signup warning. Once <em>more than</em> this
849	     * many owners already exist for the day, the new owner's {@code bulkSignupWarning} is true.
850	     */
851	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
852	
853	    /**
854	     * Computes the {@code bulkSignupWarning} for a create on the given business-day-adjusted
855	     * {@code registrationDate}: true when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners
856	     * have already been created for that date, otherwise false. The count reflects the state prior
857	     * to this create, matching how the daily-limit rule accumulates.
858	     */
859	    private boolean bulkSignupWarningFor(LocalDate registrationDate) {
860	        int count = 0;
861	        for (Owner existing : this.clinicService.findAllOwners()) {
862	            if (registrationDate.equals(existing.getRegistrationDate())) {
863	                count++;
864	            }
865	        }
866	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
867	    }
868	
869	    /**
870	     * Rolls an effective registration date forward onto a business day. A Saturday, Sunday or listed
871	     * public holiday is advanced to the next non-holiday business day; a plain weekday is returned
872	     * unchanged. This is applied to the effective registration date - whether supplied in the request
873	     * or defaulted to the server date - so the stored {@code registrationDate}, and everything derived
874	     * from it, always falls on a business day.
875	     */
876	    /**
877	     * Rejects a supplied {@code registrationDate} that lies in the future. A registration date is
878	     * only ever explicitly supplied on the request; when present it must not be later than the
879	     * current server date. A future date raises a {@link FutureRegistrationDateException}, which the
880	     * exception handler translates to a 400 Bad Request. A {@code null} date (the default, filled in
881	     * later from the server date) is accepted.
882	     */
883	    private static void rejectFutureRegistrationDate(LocalDate registrationDate) {
884	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
885	            throw new FutureRegistrationDateException(registrationDate);
886	        }
887	    }
888	
889	    /**
890	     * The fixed list of public holidays. An effective registration date that lands on any of these
891	     * is rolled forward, together with weekends, to the next non-holiday business day.
892	     */
893	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
894	        LocalDate.of(2026, 1, 1),
895	        LocalDate.of(2026, 1, 26),
896	        LocalDate.of(2026, 4, 25),
897	        LocalDate.of(2026, 12, 25),
898	        LocalDate.of(2026, 12, 28));
899	
900	    private static LocalDate toBusinessDay(LocalDate date) {
901	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
902	            date = date.plusDays(1);
903	        }
904	        return date;
905	    }
906	
907	    private static boolean isWeekend(LocalDate date) {
908	        return switch (date.getDayOfWeek()) {
909	            case SATURDAY, SUNDAY -> true;
910	            default -> false;
911	        };
912	    }
