914	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
915	    @Override
916	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
917	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
918	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
919	            OwnerDto replay = idempotentCreates.get(idempotencyKey);
920	            if (replay != null) {
921	                return new ResponseEntity<>(replay, HttpStatus.OK);
922	            }
923	        }
924	        String normalizedLine1 = null;
925	        String normalizedLine2 = null;
926	        String composedAddress;
927	        if (!isBlank(ownerFieldsDto.getAddressLine1())) {
928	            normalizedLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
929	            if (!isBlank(ownerFieldsDto.getAddressLine2())) {
930	                normalizedLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
931	            }
932	            composedAddress = normalizedLine2 == null
933	                ? normalizedLine1
934	                : normalizedLine1 + " " + normalizedLine2;
935	        } else {
936	            composedAddress = normalizeAddress(ownerFieldsDto.getAddress());
937	        }
938	        rejectMissingOrBlankFields(ownerFieldsDto, composedAddress);
939	        rejectCityAtCapacity(ownerFieldsDto.getCity());
940	        HttpHeaders headers = new HttpHeaders();
941	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
942	        owner.setAddress(composedAddress);
943	        owner.setAddressLine1(normalizedLine1);
944	        owner.setAddressLine2(normalizedLine2);
945	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
946	        owner.setTelephone(normalizedTelephone);
947	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
948	        owner.setEmail(normalizedEmail);
949	        validatePostcode(owner.getCity(), owner.getPostcode());
950	        String householdId = householdIdFor(owner.getLastName(), owner.getPostcode());
951	        rejectDuplicateIdentity(normalizedTelephone, normalizedEmail, owner.getLastName());
952	        rejectFutureRegistrationDate(owner.getRegistrationDate());
953	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
954	        LocalDate registrationDate = toBusinessDay(effectiveDate);
955	        rejectDailyOwnerLimit(registrationDate);
956	        owner.setBulkSignupWarning(bulkSignupWarningFor(registrationDate));
957	        owner.setRegistrationDate(registrationDate);
958	        String region = deriveRegion(owner.getCity(), owner.getPostcode());
959	        owner.setCustomerCode(deduplicateCustomerCode(customerCodeFor(region, normalizedTelephone, owner.getLastName())));
960	        owner.setMembershipNumber(membershipNumberFor(owner.getCustomerCode(), owner.getRegistrationDate()));
961	        owner.setHouseholdId(householdId);
962	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
963	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
964	        int membershipPoints = membershipPointsFor(owner);
965	        owner.setMembershipPoints(membershipPoints);
966	        int membershipLevel = membershipLevelForPoints(membershipPoints);
967	        // A declared household member (sharesHousehold) keeps its point-derived level; an owner
968	        // admitted into an existing household implicitly has its level capped one above the
969	        // household's current maximum.
970	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
971	            membershipLevel = capMembershipLevelByHousehold(membershipLevel, owner.getHouseholdId());
972	        }
973	        owner.setMembershipLevel(membershipLevel);
974	        Integer possibleDuplicateOf = findPossibleDuplicateOf(ownerFieldsDto, normalizedTelephone, normalizedEmail);
975	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
976	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
977	        this.clinicService.saveOwner(owner);
978	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
979	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(), owner.getMembershipNumber());
980	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
981	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
982	            idempotentCreates.put(idempotencyKey, ownerDto);
983	        }
984	        headers.setLocation(UriComponentsBuilder.newInstance()
985	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
986	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
987	    }
