8	/** audit-event: besides the audit line, emit a structured event via AUDIT
9	 * {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}. The event must carry the
10	 * owner id AND the current primary identifier (customerCode here); asserting the identifier is what
11	 * lets later checkpoints prove the event switched to the memberId. */
12	@Tag("cp53")
13	class Cp53Tests extends AcceptanceBase {
14	
15		@Test
16		void coreEventCarriesIdAndIdentifier() throws Exception {
